<?php require __DIR__.'/../includes/bootstrap.php'; require_admin(); $count=(int)$pdo->query('SELECT COUNT(*) FROM posts')->fetchColumn(); $published=(int)$pdo->query("SELECT COUNT(*) FROM posts WHERE status='published'")->fetchColumn(); $posts=$pdo->query('SELECT id,title,category,status,created_at FROM posts ORDER BY id DESC')->fetchAll(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin dashboard</title><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="row"><div><h1>Admin dashboard</h1><p>Welcome, <?=e($_SESSION['admin_name'])?></p></div><div style="text-align:right"><a href="logout.php">Log out</a> · <a href="../index.html">View website</a></div></div><div class="row"><div class="panel"><h2><?=$count?></h2>Total posts</div><div class="panel"><h2><?=$published?></h2>Published posts</div></div><p><a class="btn" href="post-edit.php">+ Create a post</a></p><div class="panel"><h2>Manage posts</h2><?php if(!$posts):?><p>No posts yet. Create your first update.</p><?php else:?><table><tr><th>Title</th><th>Type</th><th>Status</th><th>Action</th></tr><?php foreach($posts as $p):?><tr><td><?=e($p['title'])?></td><td><?=e(ucfirst($p['category']))?></td><td><?=e($p['status'])?></td><td><a href="post-edit.php?id=<?=$p['id']?>">Edit</a> · <a href="post-delete.php?id=<?=$p['id']?>">Delete</a></td></tr><?php endforeach;?></table><?php endif;?></div></div></body></html>